-- UUIDs are generated by the application; no PostgreSQL extensions are required.
CREATE TABLE users (
    id UUID PRIMARY KEY,
    email VARCHAR(254) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'DISABLED')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT users_email_normalized CHECK (email = lower(btrim(email)) AND email <> ''),
    CONSTRAINT users_email_unique UNIQUE (email)
);

CREATE TABLE user_profiles (
    user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT,
    full_name VARCHAR(120) NOT NULL CHECK (btrim(full_name) <> ''),
    phone_number VARCHAR(32),
    bio VARCHAR(1000),
    avatar_url VARCHAR(2048),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE driver_profiles (
    user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE vehicles (
    id UUID PRIMARY KEY,
    driver_id UUID NOT NULL REFERENCES driver_profiles(user_id) ON DELETE RESTRICT,
    make VARCHAR(80) NOT NULL CHECK (btrim(make) <> ''),
    model VARCHAR(80) NOT NULL CHECK (btrim(model) <> ''),
    color VARCHAR(40),
    registration_number VARCHAR(32) NOT NULL CHECK (btrim(registration_number) <> ''),
    passenger_capacity SMALLINT NOT NULL CHECK (passenger_capacity > 0),
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT vehicles_id_driver_unique UNIQUE (id, driver_id)
);
CREATE INDEX vehicles_driver_idx ON vehicles(driver_id);

CREATE TABLE rides (
    id UUID PRIMARY KEY,
    driver_id UUID NOT NULL REFERENCES driver_profiles(user_id) ON DELETE RESTRICT,
    vehicle_id UUID NOT NULL,
    source_name VARCHAR(200) NOT NULL CHECK (btrim(source_name) <> ''),
    source_locality_id VARCHAR(120) NOT NULL CHECK (btrim(source_locality_id) <> ''),
    source_latitude NUMERIC(9,6) CHECK (source_latitude BETWEEN -90 AND 90),
    source_longitude NUMERIC(9,6) CHECK (source_longitude BETWEEN -180 AND 180),
    destination_name VARCHAR(200) NOT NULL CHECK (btrim(destination_name) <> ''),
    destination_locality_id VARCHAR(120) NOT NULL CHECK (btrim(destination_locality_id) <> ''),
    destination_latitude NUMERIC(9,6) CHECK (destination_latitude BETWEEN -90 AND 90),
    destination_longitude NUMERIC(9,6) CHECK (destination_longitude BETWEEN -180 AND 180),
    departure_at TIMESTAMPTZ NOT NULL,
    departure_time_zone VARCHAR(64) NOT NULL CHECK (btrim(departure_time_zone) <> ''),
    total_seats SMALLINT NOT NULL CHECK (total_seats > 0),
    available_seats SMALLINT NOT NULL,
    price_per_seat NUMERIC(12,2) NOT NULL CHECK (price_per_seat >= 0),
    currency VARCHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'PUBLISHED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED')),
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    cancellation_reason VARCHAR(500),
    started_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    cancelled_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT rides_vehicle_owner_fk FOREIGN KEY (vehicle_id, driver_id) REFERENCES vehicles(id, driver_id) ON DELETE RESTRICT,
    CONSTRAINT rides_seat_bounds CHECK (available_seats BETWEEN 0 AND total_seats),
    CONSTRAINT rides_source_coordinates CHECK ((source_latitude IS NULL) = (source_longitude IS NULL)),
    CONSTRAINT rides_destination_coordinates CHECK ((destination_latitude IS NULL) = (destination_longitude IS NULL)),
    CONSTRAINT rides_different_localities CHECK (source_locality_id <> destination_locality_id)
);
CREATE INDEX rides_search_idx ON rides(source_locality_id, destination_locality_id, departure_at) WHERE status = 'PUBLISHED';
CREATE INDEX rides_driver_history_idx ON rides(driver_id, departure_at DESC);
CREATE INDEX rides_vehicle_idx ON rides(vehicle_id, driver_id);

CREATE TABLE bookings (
    id UUID PRIMARY KEY,
    ride_id UUID NOT NULL REFERENCES rides(id) ON DELETE RESTRICT,
    passenger_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    seats_booked SMALLINT NOT NULL CHECK (seats_booked > 0),
    price_per_seat_snapshot NUMERIC(12,2) NOT NULL CHECK (price_per_seat_snapshot >= 0),
    currency VARCHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    status VARCHAR(30) NOT NULL DEFAULT 'CONFIRMED' CHECK (status IN ('CONFIRMED', 'CANCELLED_BY_PASSENGER', 'CANCELLED_BY_DRIVER')),
    cancelled_by UUID REFERENCES users(id) ON DELETE RESTRICT,
    cancellation_reason VARCHAR(500),
    cancelled_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT bookings_cancellation_consistency CHECK (
        (status = 'CONFIRMED' AND cancelled_at IS NULL AND cancelled_by IS NULL)
        OR (status <> 'CONFIRMED' AND cancelled_at IS NOT NULL AND cancelled_by IS NOT NULL)
    )
);
CREATE UNIQUE INDEX bookings_active_passenger_unique ON bookings(ride_id, passenger_id) WHERE status = 'CONFIRMED';
CREATE INDEX bookings_passenger_history_idx ON bookings(passenger_id, created_at DESC);
CREATE INDEX bookings_ride_idx ON bookings(ride_id);
CREATE INDEX bookings_cancelled_by_idx ON bookings(cancelled_by) WHERE cancelled_by IS NOT NULL;

-- Refresh-token persistence and transaction-based seat allocation belong to later phases.
-- updated_at is maintained by the application when mutation services are introduced.
